'use strict';
const $=s=>document.querySelector(s), app=$('#app'), K={progress:'gtoTrainer.progress.v1',mistakes:'gtoTrainer.mistakes.v1',settings:'gtoTrainer.settings.v1',daily:'gtoTrainer.daily.v1'};
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(K[k]))??d}catch{return d}},write=(k,v)=>{try{localStorage.setItem(K[k],JSON.stringify(v))}catch{toast('Storage is full or unavailable. Export your progress to keep it.')}};
let progress=read('progress',[]),mistakes=read('mistakes',[]),settings=read('settings',{tableSize:4,fourColor:true,length:10,sound:false}),daily=read('daily',{}),datasets=[],learn=[],sources=[],screen='home',selectedMode=0,filters={},session=null,chartId='rfi-LJ',cardId=0,learnGroup=null;
const modes=[["Quick Drill", "Ten hands, every seat. This is your baseline, not a warm-up."], ["Preflop by Position", "One seat at a time, until the opens are automatic."], ["Preflop by Spot", "Opens, defenses, and the 3-bets you keep getting wrong."], ["Postflop Trainer", "Read the board, do the math, then trust the call."], ["Mistake Review", "The hands you missed, back on the table until they stick."], ["Charts", "Every range in the baseline, hand by hand."], ["Daily Hand", "Two spots a day. Small habit, compounding edge."], ["Concept Quiz", "Definitions and math from your own notes, tested cold."], ["Learn", "Your study notes, one idea at a time. Personal notes, not solver output."]];
modes.push(['Equity Lab','Count your outs. Price your draw.']);
modes.push(['Villain Study','Read Rob, Ben, Alex and Ruining. Practice the exploit, with the evidence.']);
const glossary={GTO:'Game theory optimal play is a balanced strategy that cannot be exploited by a perfectly responding opponent.',RFI:'Raise first in means opening the pot with a raise after everyone before you folds.','3-bet':'A 3-bet is the first re-raise after an opening raise.','4-bet':'A 4-bet is a re-raise of a 3-bet.',polarized:'A polarized range contains strong value hands and bluffs, with fewer medium-strength hands.','linear or merged range':'A linear range takes the strongest hands in order, including medium-strength value hands.',blocker:'A blocker is a card you hold that reduces the combinations of hands an opponent can have.','pot odds':'Pot odds give the minimum equity a call needs to break even, ignoring future betting.',MDF:'Minimum defense frequency is the share of a range that continues to prevent an automatic-profit bluff.',alpha:'Alpha is the minimum fold frequency a pure bluff needs to break even.','c-bet':'A continuation bet is a bet by the player who was the aggressor on the previous street.','range advantage':'Range advantage means one player’s overall range has more equity or stronger hands on a board.',SPR:'Stack-to-pot ratio is the effective remaining stack divided by the current pot.','equity realization':'Equity realization is how much of a hand’s raw showdown equity it actually captures through betting.'};
Object.assign(glossary,{'Isolation raise':'A raise over a limp. This four-handed baseline uses 4bb total from BB against the SB completion.','Limp response':'After SB completes to 1bb and BB raises to 4bb total, SB can fold, call 3bb more, or limp-raise.','Limp':'Entering an unraised pot by calling the big blind. SB completes from 0.5bb to 1bb.','Outs':'The unseen cards that improve your hand. Equity Lab counts clean outs: cards completing the named draw that put you ahead of the shown villain hand. A flush draw usually has nine draw-completing cards, but a heart that gives villain a full house is not a clean out.','Rule of 2 and 4':'A shortcut for draw equity. Multiply your outs by 4 with two cards to come, or by 2 with one card to come, to estimate your chance of completing the draw as a percentage.'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>Math.round(x)+'%',combo=h=>h.length===2?6:h.endsWith('s')?4:12, rand=a=>a[Math.floor(Math.random()*a.length)],pct=x=>(100*x).toFixed(0)+'%',day=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const modeLabel=()=>settings.tableSize+'-handed cash';
const rangeKey='gtoTrainer.importedRanges.v1';
let importedRanges=[],fourHandedBaselines=[];
settings.tableSize=settings.tableSize===6?6:4;
const rowSize=x=>x.tableSize===4?4:6;
const seatsFor=n=>n===4?['CO','BTN','SB','BB']:['LJ','HJ','CO','BTN','SB','BB'];
const rangeNode=d=>[d.hero,d.villain||'',d.spot].join('|');
const allRangeData=()=>datasets.concat(fourHandedBaselines,importedRanges);
const rangesFor=(n=settings.tableSize)=>{const imports=importedRanges.filter(d=>d.tableSize===n);return n===6?datasets.concat(imports):fourHandedBaselines.filter(d=>!imports.some(x=>rangeNode(x)===rangeNode(d))).concat(imports)};
function removeRangeImport(id){const next=importedRanges.filter(d=>d.id!==id);localStorage.setItem(rangeKey,JSON.stringify(next));importedRanges=next;showSettings();toast('Import removed. Matching constructed baseline ranges are active again.')}
try{const saved=JSON.parse(localStorage.getItem(rangeKey)||'[]');if(Array.isArray(saved))importedRanges=validateRanges({ranges:saved}).ranges}catch{}

function tableSwitch(){return `<div class="table-switch" role="group" aria-label="Table size">${[4,6].map(n=>`<button data-table-size="${n}" aria-pressed="${settings.tableSize===n}" class="${settings.tableSize===n?'selected':''}">${n}-handed</button>`).join('')}</div>`}
function changeTableSize(n){if(![4,6].includes(n)||settings.tableSize===n)return;if(screen==='session'&&session&&!confirm('Change table size and end this drill? Completed answers are already saved.'))return;settings.tableSize=n;write('settings',settings);session=null;filters={};chartId='';go(screen==='session'||screen==='results'?'home':screen==='card'?'learn':screen)}
function missingRangeMessage(){return `<section class="panel"><h3>No ${settings.tableSize}-handed data loaded for this spot</h3><p class="muted">Import a solver export in Settings. Each table size uses its own data; six-handed grids are never substituted.</p><button data-go="settings">Import ranges</button></section>`}
function validateRanges(obj){
 const rows=Array.isArray(obj)?obj:obj.ranges;if(!Array.isArray(rows)||!rows.length)throw Error('Provide a non-empty ranges array.');
 const known=['RFI','Facing an Open','Facing a 3-Bet','Facing a 4-Bet','Facing a Limp','SB vs BB iso-raise'],ranks='AKQJT98765432',hands=new Set();for(let i=0;i<13;i++)for(let j=0;j<13;j++)hands.add(i===j?ranks[i]+ranks[j]:i<j?ranks[i]+ranks[j]+'s':ranks[j]+ranks[i]+'o');
 const ids=new Set(),ranges=rows.map((d,i)=>{
  const fail=m=>{throw Error('Range '+(i+1)+': '+m)};
  if(![4,6].includes(d.tableSize)||d.stackBb!==100||d.rake!==0)fail('tableSize must be 4 or 6, stackBb 100, and rake 0.');
  if(!seatsFor(d.tableSize).includes(d.hero)||d.villain&&!seatsFor(d.tableSize).includes(d.villain)||d.hero===d.villain)fail('invalid positions for this table size.');
  if(!known.includes(d.spot)||d.spot!=='RFI'&&!d.villain)fail('supply a supported spot and opponent seat.');
  if(d.spot==='Facing a Limp'&&(d.hero!=='BB'||d.villain!=='SB'))fail('Facing a Limp requires BB vs SB.');
  if(d.spot==='SB vs BB iso-raise'&&(d.hero!=='SB'||d.villain!=='BB'))fail('iso-raise response requires SB vs BB.');
  if(typeof d.source!=='string'||!d.source.trim())fail('a solver export source is required.');
  if(!Array.isArray(d.cells)||d.cells.length!==169||new Set(d.cells.map(c=>c.hand)).size!==169)fail('provide all 169 unique hand classes.');
  const actions=['Raise','Call','Fold','Limp','Check','3-Bet','4-Bet','5-Bet'];
  const cells=d.cells.map(c=>{if(!hands.has(c.hand)||!c.frequencies||typeof c.frequencies!=='object')fail('invalid hand or frequencies.');let entries=Object.entries(c.frequencies);if(!entries.length||entries.some(([a,f])=>!actions.includes(a)||!Number.isFinite(f)||f<0||f>1)||Math.abs(entries.reduce((a,[,f])=>a+f,0)-1)>1e-6)fail(c.hand+' frequencies must be 0–1 and sum to 1.');return {...c,action:entries.slice().sort((a,b)=>b[1]-a[1])[0][0]}});
  if(cells.some(c=>(c.frequencies.Limp||0)>0&&!(d.hero==='SB'&&d.spot==='RFI')))fail('Limp is supported only for SB first in.');
  if(cells.some(c=>(c.frequencies.Check||0)>0&&d.spot!=='Facing a Limp'))fail('Preflop Check requires Facing a Limp.');
  if(d.spot==='Facing a Limp'&&cells.some(c=>Object.entries(c.frequencies).some(([a,f])=>f>0&&!['Raise','Check'].includes(a))))fail('BB vs SB limp uses Raise or Check; checking is free.');
  if(d.eligible&&(!Array.isArray(d.eligible)||!d.eligible.length||d.eligible.some(h=>!hands.has(h))))fail('invalid eligible hand classes.');
  if(d.spot!=='RFI'&&(!Number.isFinite(d.pot)||d.pot<=0||typeof d.line!=='string'||!d.line.trim()||!Number.isFinite(d.openSize)||d.openSize<=0||!['Facing an Open','Facing a Limp'].includes(d.spot)&&(!Number.isFinite(d.threeSize)||d.threeSize<=0)))fail('non-RFI exports require pot, line, openSize and (when facing a re-raise) threeSize, all sizes in bb.');
  if(!d.betSizes||!Array.isArray(d.betSizes)||!d.betSizes.length||d.betSizes.some(n=>!Number.isFinite(n)||n<=0||n>100))fail('provide betSizes in bb, greater than 0 and at most 100.');
  const id='import-'+d.tableSize+'-'+d.hero+'-'+(d.villain||'none')+'-'+d.spot.replaceAll(' ','-');if(ids.has(id))fail('duplicate seat and spot.');ids.add(id);
  const eligible=d.eligible||[...hands],den=eligible.reduce((a,h)=>a+combo(h),0),targets=d.targets||Object.fromEntries([...new Set(cells.flatMap(c=>Object.keys(c.frequencies)))].map(a=>[a,cells.filter(c=>eligible.includes(c.hand)).reduce((v,c)=>v+combo(c.hand)*(c.frequencies[a]||0),0)/den*100]));
  if(Object.entries(targets).some(([a,n])=>!actions.includes(a)||!Number.isFinite(n)||n<0||n>100))fail('invalid targets.');
  return {...d,id,cells,targets,label:'Imported solver export',notes:d.notes||'Imported frequencies. Targets are supplied by the export or computed from its combination-weighted cells.'};
 });return {ranges};
}
function rangeReport(){return [4,6].map(n=>{const rs=rangesFor(n),expected=seatsFor(n).flatMap(hero=>['RFI','Facing an Open','Facing a 3-Bet','Facing a 4-Bet'].filter(spot=>spot!=='RFI'||hero!=='BB').map(spot=>({hero,spot}))),missing=expected.filter(x=>!rs.some(d=>d.hero===x.hero&&d.spot===x.spot));return `<p><strong>${n}-handed: ${rs.length} loaded grids.</strong></p><p class="source">Missing position/scenario groups: ${missing.length?missing.map(x=>esc(x.hero+' / '+x.spot)).join(' · '):'none'}. Opponent-specific matchups must also be supplied.</p>`}).join('')}
async function importRanges(file){try{const parsed=validateRanges(JSON.parse(await file.text())),incoming=parsed.ranges,keep=importedRanges.filter(d=>!incoming.some(x=>x.id===d.id)),next=keep.concat(incoming);localStorage.setItem(rangeKey,JSON.stringify(next));importedRanges=next;for(let d of importedRanges)for(let c of d.cells)c.classification=classify(d,c);showSettings();toast(incoming.length+' solver grids imported. Missing groups are listed below.')}catch(e){toast('Import rejected: '+e.message)}}

function toast(s){document.querySelector('.toast')?.remove();let el=document.createElement('div');el.className='toast';el.textContent=s;document.body.append(el);setTimeout(()=>el.remove(),3500)}

