function shell(body,active='Train'){app.innerHTML=`<div class="wrap"><header class="top"><button class="brand" data-go="home"><span class="logo">${tiger}</span> POT GEOMETRY</button><nav class="nav">${['Train','Charts','Learn','Opponents','Progress'].map(t=>`<button class="${active===t?'active':''}" data-go="${{Train:'home',Charts:'charts',Learn:'learn',Progress:'progress',Opponents:'opponents'}[t]}">${t}</button>`).join('')}<button class="optional" data-go="settings" aria-label="Settings">${svgIcon("gear")}</button></nav><div class="header-table"><span class="source">${modeLabel()} · 100bb</span>${tableSwitch()}</div></header>${body}<footer class="footer"><span>Pot Geometry · Built for one home game's study group.</span><span><button data-go="methodology">Methodology</button> &nbsp; / &nbsp; <button data-go="glossary">Glossary</button> &nbsp; / &nbsp; <button data-go="settings">Settings</button></span></footer></div>`}
function due(){return mistakes.filter(m=>rowSize(m.spot)===settings.tableSize&&m.due<=Date.now()&&(m.spot.kind!=='pre'||rowSize(m.spot)===6||rangesFor(4).some(d=>d.id===m.spot.dataset)))}function accuracy(items){items=items.filter(x=>Number.isFinite(x.score));return items.length?pct(items.reduce((a,b)=>a+b.score,0)/items.length):'—'}
function home(){landingHome()}
function go(s){screen=s;document.body.classList.toggle('two-color',!settings.fourColor);({home,charts,opponents:showOpponents,villainReview:showVillainReview,progress:showProgress,learn:showLearn,settings:showSettings,methodology,glossary:showGlossary,setup,session:renderSession}[s]||home)();window.scrollTo(0,0)}
function positionMatchups(){
 if(settings.tableSize!==4||selectedMode!==1||!['SB','BB'].includes(filters.choice))return '';
 const ds=rangesFor().filter(d=>d.hero===filters.choice&&(filters.choice==='BB'?['Facing an Open','Facing a Limp'].includes(d.spot):['RFI','SB vs BB iso-raise'].includes(d.spot)));
 if(filters.matchup&&!ds.some(d=>rangeNode(d)===filters.matchup))filters.matchup='';
 return `<label class="position-matchup">Matchup<select id="position-matchup"><option value="">All matchups</option>${ds.map(d=>`<option value="${esc(rangeNode(d))}" ${filters.matchup===rangeNode(d)?'selected':''}>${d.spot==='RFI'?'First in':d.spot==='Facing a Limp'?'vs SB limp':d.spot==='SB vs BB iso-raise'?'vs BB iso-raise':'vs '+d.villain+' open'}</option>`).join('')}</select></label>`;
}
function setup(){if(selectedMode===10){villainSetup();return}if(selectedMode===9){equitySetup();return}let i=selectedMode;let options=i===1?(settings.tableSize===4?['CO','BTN','SB','BB']:['LJ','HJ','CO','BTN','SB','BB']):i===2?['Raise First In','Facing an Open','Facing a 3-Bet','Facing a 4-Bet']:i===3?['Facing a Bet','C-Bet or Check','River Decisions']:i===7?['All groups',...new Set(learn.map(c=>c.group))]:[];if(!filters.choice||!options.includes(filters.choice))filters.choice=options[0];shell(`<div class="page"><button class="back" data-go="home">${svgIcon("back")} All practice modes</button><div class="eyebrow">Deliberate practice</div><h1>${modes[i][0]}</h1><p class="muted">${modes[i][1]}</p>${options.length?`<div class="choices">${options.map(o=>`<button class="${filters.choice===o?'selected':''}" data-choice="${esc(o)}">${o==='BB'?'BB defense':seatLabel(groupLabel(o))}</button>`).join('')}</div>`:''}${positionMatchups()}<div class="panel"><h3>${i===6?'Two spots. One daily habit.':i===4?due().length+' spots ready to revisit':settings.length==='endless'?'An open-ended practice session':settings.length+' hands. One decision at a time.'}</h3><p class="muted">${modeLabel()} · 100bb · No rake</p>${tableSwitch()}${[0,1,2,3,6].includes(i)?'<p class="source">Grading mode: Baseline. Opponent exploit grading is available in Villain Study.</p>':''}<p class="muted">${i===3?'Postflop strategy is heuristic. Pot odds, MDF, and alpha use exact formulas.':i===7?"Tiger’s study notes · personal notes, not solver output.":i===4?'Two consecutive correct reviews retire a spot. Miss it again and we’ll bring it back.':'Published seeds and clearly labeled constructed ranges. Instant feedback after every hand.'}</p><button class="primary start" data-start ${i===4&&!due().length||[0,1,2,6].includes(i)&&!(i===6?rangesFor().filter(d=>d.spot==='RFI'&&['CO','BTN','SB'].includes(d.hero)):eligibleDatasets()).length?'disabled':''}>Start ${i===6?'daily hands':'practice'} ${svgIcon('next')}</button></div>${i===4?'<button data-go="villainReview">Villain mistake details & retry</button>':''}<p class="source">${settings.tableSize===4?(rangesFor().length?'Constructed baseline ranges · 100bb · No rake · No ante. Imported solver grids override matching spots.':'No 4-handed ranges loaded. Import solver data in Settings.'):'Keyboard: F fold · C call/check · R raise/bet · 1–4 sizing · Enter next'}</p></div>`)}
function handCards(h){if(h.length===2)return[h[0]+'s',h[1]+'h'];return[h[0]+'s',h[1]+(h.endsWith('s')?'s':'h')]}
function card(c){let suits={s:['♠','spades'],h:['♥','hearts'],d:['♦','diamonds'],c:['♣','clubs']},[symbol,cls]=suits[c[1]];return `<div class="card ${cls}" aria-label="${c[0]} ${cls}"><span>${c[0]}</span><span class="suit">${symbol}</span></div>`}
const colors={Limp:'var(--cyan)',Raise:'var(--raise)','3-Bet':'var(--raise)','4-Bet':'var(--raise)',Bet:'var(--raise)',Call:'var(--call)',Check:'var(--call)',Fold:'var(--fold)'};
function term(t){return `${esc(t)}<button class="help" data-term="${esc(t)}" aria-label="Define ${esc(t)}">${svgIcon("help")}</button>`}
function strength(h){const r='23456789TJQKA',a=r.indexOf(h[0])+2,b=r.indexOf(h[1])+2;return a===b?a*3+25:a*2+b+(h.endsWith('s')?5:0)+(a-b===1?4:0)+(a===14?4:0)}
function classify(d,c){if(c.classification)return c.classification;let trap=(c.action==='Fold'&&c.hand.endsWith('o')&&strength(c.hand)>33)||(c.action.includes('Bet')&&['A5s','A4s','65s','76s'].includes(c.hand));if(trap)return 'trap';let f=Object.values(c.frequencies);if(f.some(x=>x>.001&&x<.999))return 'boundary';let action=c.action;let near=d.cells.some(x=>x.action!==action&&Math.abs(strength(x.hand)-strength(c.hand))<=2&&x.hand.slice(-1)===c.hand.slice(-1));if(near)return 'boundary';if((action==='Fold'&&strength(c.hand)>40)||(action.includes('Bet')&&['A5s','A4s','65s','76s'].includes(c.hand)))return 'trap';return 'clear'}
function eligibleDatasets(){let ds=rangesFor();if(selectedMode===1){ds=ds.filter(d=>d.hero===filters.choice&&(settings.tableSize===4?filters.choice==='BB'?['Facing an Open','Facing a Limp'].includes(d.spot):filters.choice==='SB'?['RFI','SB vs BB iso-raise'].includes(d.spot):d.spot==='RFI':filters.choice==='BB'?d.spot==='Facing an Open':d.spot==='RFI'));if(filters.matchup)ds=ds.filter(d=>rangeNode(d)===filters.matchup)}if(selectedMode===2)ds=ds.filter(d=>d.spot===({'Raise First In':'RFI'}[filters.choice]||filters.choice));return ds}
function preSpot(ds=eligibleDatasets(),rng=Math.random){let pool=[];for(let d of ds)for(let c of d.cells){if(d.eligible&&!d.eligible.includes(c.hand))continue;if(session?.used.has(d.id+':'+c.hand))continue;pool.push({d,c,type:c.classification||classify(d,c)})}if(!pool.length)return null;let sequence=['boundary','clear','boundary','trap','clear','boundary','clear','boundary','trap','boundary'],t=sequence[(session?.index||0)%10],filtered=pool.filter(p=>p.type===t);let {d,c,type}=(filtered.length?filtered:pool)[Math.floor(rng()*(filtered.length||pool.length))];return {kind:'pre',tableSize:d.tableSize||6,stackBb:100,rake:0,betSizes:d.betSizes,id:d.id+':'+c.hand,dataset:d.id,hand:c.hand,cards:handCards(c.hand),hero:d.hero,villain:d.villain,spot:d.spot,openSize:d.openSize??(d.hero==='SB'?3:2.5),threeSize:d.threeSize??(d.villain==='BTN'?7.5:d.hero==='SB'?12:10),frequencies:c.frequencies,source:d.source,label:d.label,classification:type,line:d.line??(d.spot==='RFI'?'Folded to you. What’s your opening decision?':d.spot==='Facing an Open'?`${d.villain} opens to ${d.villain==='SB'?3:2.5}bb. Action is on you.`:`You opened to ${d.hero==='SB'?3:2.5}bb. ${d.villain} 3-bets to ${d.villain==='BTN'?7.5:d.hero==='SB'?12:10}bb.`),pot:d.pot??(d.spot==='RFI'?1.5:d.spot==='Facing an Open'?(d.villain==='SB'?3.5:4):(d.hero==='SB'?3:2.5)+(d.villain==='BTN'?7.5:d.hero==='SB'?12:10)+1.5-(d.hero==='SB'?.5:0)-(d.villain==='BB'?1:0)),reason:d.reason??(d.betSizes?'The imported solver frequencies apply to this exact seat and action context.':d.spot==='RFI'?`${d.hero==='BTN'?'Only the blinds are behind the button, so the opening range is wider.':d.hero==='LJ'?'Five players remain behind the first seat, so its range stays tight.':d.hero==='SB'?'The small blind uses a raise-or-fold baseline against one remaining player.':'The opening range widens as fewer players remain behind you.'}`:`${d.spot==='Facing an Open'?'The construction balances value re-raises with playable calls against this opener.':'The response is measured within your opening range, preserving premium 4-bets and playable calls.'}`)}}
