function makePacks(){let packs=[[],[],[]];const add=(p,hand,board,action,reason,extra={})=>packs[p].push({kind:'post',id:'P'+(p+1)+'-'+packs[p].length,pack:p,spot:['Facing a Bet','C-Bet or Check','River Decisions'][p],hero:p===1?'BTN':'BB',villain:p===1?'BB':'BTN',cards:hand.split(' '),board:board.split(' '),frequencies:{[action]:1},answer:action,reason,source:'Appendix A4 / Section 6 · curated heuristic',label:'Heuristic · not solver output',pot:20,bet:10,line:p===1?'You raised preflop. The big blind called and checks to you.':'Single-raised pot. Villain bets; action is on you.',...extra});
let p1=[['As Qs','Ks 8s 2d','Call',.5, .35,'A nut flush draw has 35% assumed training equity, which clears the call threshold.'],['9h 9c','Kd 9s 4h','Call',.75,.8,'A set has 80% assumed training equity, so continuing clears the call threshold.'],['Ah 8d','Ks Qs 2c','Fold',1,.12,'Ace-high with no draw has only 12% assumed training equity here, below the threshold.'],['Jh Th','Qh 9c 2s','Call',.33,.32,'An open-ended draw has 32% assumed training equity, above the price of this small bet.'],['7c 7d','As Kh Qd','Fold',1.5,.1,'An underpair has 10% assumed training equity, too little against this large out-of-position bet.'],['Ac Kd','Kh 8s 3d','Call',.25,.7,'Top pair has 70% assumed training equity here and easily clears the call threshold.'],['8s 7s','As Ts 2d 4c','Fold',2,.19,'A turn flush draw has 19% assumed training equity, below the 40% price of a twice-pot bet.'],['Qd Jc','Qs 7h 3d 2c','Call',.67,.6,'Top pair has 60% assumed training equity here, comfortably above the threshold.'],['6h 5h','9h 8c 2d','Fold',.75,.16,'A gutshot has 16% assumed training equity here, below the 30% price.'],['Td Tc','9s 7h 3c','Call',.5,.65,'An overpair has 65% assumed training equity here, enough to continue.'],['Ad 4d','Kd 8d 2s','Call',.33,.4,'The nut flush draw has 40% assumed training equity here, enough against a small bet.'],['Js 9c','Ah Kh 7d 2c','Fold',1,.05,'No pair and no meaningful draw have 5% assumed training equity, so fold to a pot-sized bet.']];
for(let [h,b,a,f,e,r] of p1)add(0,h,b,a,r,{bet:20*f,equity:e,engine:'Exact math · stipulated equity',line:'Villain bets. Use the stated equity assumption to decide whether calling breaks even.',label:'Heuristic equity assumption · exact pot-odds verdict',equityNote:'Equity is a training assumption, not a solver calculation.'});
let p2=[['As Qd','Ah 7c 2d','Bet','small','Dry ace-high boards favor the preflop raiser, so use a small continuation bet.'],['Ks Qh','Kd 8c 2s','Bet','small','A dry king-high board favors the raiser’s high-card range, supporting a small bet.'],['Qh Jc','As 8d 3c','Bet','small','This dry ace-high board supports a small range-advantage bluff.'],['Ah Kd','Qd 7c 2s','Bet','small','A dry high-card board lets the raiser apply pressure with a small bet.'],['Ac Ad','Js Th 9h','Bet','large','A wet connected board calls for a more polarized range and a larger value bet.'],['Kh Qh','Jh Tc 9h','Bet','large','A strong straight on this wet connected board belongs in the larger polarized betting range.'],['As 4s','Js Ts 9c','Bet','large','A nut flush draw supplies a strong semi-bluff on a wet connected board; use the larger class.'],['Qd Jc','Jh Ts 9s','Check',null,'Medium top pair on a wet connected board fits the checking range rather than polarized betting.'],['As Kd','6h 5c 4d','Check',null,'A low connected board favors the caller’s range, so the raiser checks ace-high.'],['Kh Qs','7c 5d 4h','Check',null,'Low connected cards favor the caller, so checking protects the raiser’s weaker range.'],['Ad Jd','6s 4c 3h','Check',null,'The caller connects with this low board more often, so check the missed high cards.'],['9s 9d','8h 7h 6c','Check',null,'A medium overpair on a wet board prefers pot control in this heuristic pack.']];for(let[h,b,a,sizeClass,r]of p2)add(1,h,b,a,r,{sizeClass,bet:0});
let p3=[['Ac Qd','Qs 8c 5c 2d 2h','Call','The queen blocks Qx value while neither card blocks the assumed JT/97 missed-draw bluffs, favoring a call against that stated range.'],['Js Qh','Qc 9h 6d 3s 2c','Fold','The jack blocks missed JT bluffs, weakening this bluff-catcher against the stated value-heavy range.'],['As Jd','Ah Th 7c 4s 2d','Call','The ace blocks top-set and two-pair value while leaving missed heart draws available to bluff.'],['Kh Qh','Ks Th 7h 4c 2d','Fold','Two hearts remove missed flush bluffs, so this top-pair bluff-catcher folds against the stated range.'],['9c 9d','As 9h 7s 3d 2c','Bet','A set beats the stated calling range of aces and two pair; holding two nines blocks sets but leaves many Ax calls.'],['Ad Kc','As Qh 8d 4s 2c','Bet','Top pair top kicker beats the stated AQ-excluded weaker-Ax calling range; a king blocks AK ties and leaves weaker aces.'],['Qc Qd','As Kh 8c 4d 2s','Check','Queens only beat missed draws in the stated range and block QJ bluffs, so checking is preferable to thin value.'],['Jh Jd','Ks 9c 7h 4s 2d','Check','Jacks only beat bluffs in the stated calling model and block JT misses, so no worse calling range supports a value bet.'],['Ac Qd','Qs 9h 6h 3d 2c','Call','The queen blocks top-set and Qx value while neither card blocks missed hearts, favoring a bluff-catch.'],['Ah Qh','Qs 9h 6h 3d 2c','Fold','Holding two hearts removes missed flush draws from villain’s bluffs, making this the weaker bluff-catcher.'],['7c 7d','Ks 7h 4c 2d 2s','Bet','A full house beats the stated Kx and trips calling range; two sevens block rival full houses but leave Kx calls.'],['Ac 5d','As Qc 8h 4s 2d','Check','Weak top pair does not beat the stated stronger-Ax calling range; the ace blocks some value but does not create worse calls.']];for(let[h,b,a,r]of p3)add(2,h,b,a,r,{bet:a==='Bet'||a==='Check'?0:20,sizeClass:a==='Bet'?'large':null,line:a==='Bet'||a==='Check'?'River. Villain checks; choose value bet or check against the stated calling range.':'River. Villain bets pot. Evaluate blockers using the stated range assumption.'});return packs}
const packs=makePacks();
function postSpot(pack=selectedMode===3?['Facing a Bet','C-Bet or Check','River Decisions'].indexOf(filters.choice):0,rng=Math.random){let ps=packs[pack].filter(s=>!session?.used.has(s.id));if(!ps.length)return null;return JSON.parse(JSON.stringify(ps[Math.floor(rng()*ps.length)]))}
function seeded(s){let n=2166136261;for(let c of s)n=Math.imul(n^c.charCodeAt(0),16777619);return()=>{n+=0x6d2b79f5;let t=n;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
function quizSpot(){let group=filters.choice;let available=learn.filter(c=>!group||group==='All groups'||c.group===group),c=rand(available);if(!c)return null;let q={kind:'quiz',id:'quiz-'+c.id+'-'+Math.random(),spot:'Concept Quiz',hero:'Concepts',cardId:c.id,source:c.source,label:c.label,answer:0,options:[],question:'',reason:''};
if(c.group==='Math'){
 let b=rand([.25,1/3,.5,2/3,.75,1]),t=Math.floor(Math.random()*7),value,formula;
 q.cardId=learn.find(x=>x.title.startsWith(['Pot normalization','Alpha','MDF','Rule of 2','Fold equity discounting','EV (','Convergence'][t]))?.id??c.id;if(t<3){let name=['pot odds','alpha','MDF'][t];value=t===0?b/(1+2*b):t===1?b/(1+b):1/(1+b);q.question=`Facing a ${fmt(b*100)}-pot bet, what ${t===1?'fold frequency does a pure bluff need':t===2?'share of the range is MDF':'equity is needed to call'}?`;formula=`${name} = ${t===0?`${b.toFixed(3)} ÷ (1 + 2 × ${b.toFixed(3)})`:t===1?`${b.toFixed(3)} ÷ (1 + ${b.toFixed(3)})`:`1 ÷ (1 + ${b.toFixed(3)})`} = ${pct(value)}.`;q.options=[pct(value),pct(Math.min(.99,value+.12)),pct(Math.max(.01,value-.1)),pct(Math.min(.98,value+.25))]}
 else if(t===3){let outs=rand([4,8,9,12]),turn=rand([true,false]);value=outs*(turn?2:4);q.question=`With ${outs} outs on the ${turn?'turn':'flop'}, what does the rule of 2 and 4 estimate?`;formula=`${outs} outs × ${turn?2:4} = ${value}% approximate equity.`;q.options=[value+'%',value+8+'%',Math.max(1,value-7)+'%',value+16+'%']}
 else if(t===4){q.question='Pot odds are 20% and there is a 30% risk of a raise behind you. What required equity do the notes use?';q.options=['About 28.5%','20%','14%','50%'];formula='Required equity = 20% ÷ 0.70 = 28.57%, written as 28.5% in the notes.'}
 else if(t===5){q.question='Calling $50 into a $100 pot at 40% equity: what is the EV?';q.options=['+$30','−$10','+$60','$0'];formula='EV = (0.40 × $150) − (0.60 × $50) = $60 − $30 = +$30.'}
 else{q.question='Quarter-pot bet: which set correctly connects hand-level pot odds and range-level defense?';q.options=['Pot odds 17% · alpha 20% · MDF 80%','Pot odds 20% · alpha 17% · MDF 83%','Pot odds 25% · alpha 25% · MDF 75%','Pot odds 17% · alpha 80% · MDF 20%'];formula='0.25 ÷ 1.5 ≈ 17% pot odds; 0.25 ÷ 1.25 = 20% alpha; 1 − 20% = 80% MDF; the weakest defending hand breaks even in the idealized notes example.'}q.reason=formula;
}else if(c.group==='Position Principles'){
const qs=[['Facing BTN’s 3-bet rather than CO’s, what do Tiger’s UTG notes suggest?',['4-bet less: about 8% vs 10–11%','4-bet more: about 20%','Always fold AK','Use the same response regardless of position'],'The notes prefer capturing BTN’s polarized bluffs through calls rather than folding them out with a 4-bet.'],['CO faces a BB 3-bet instead of an SB 3-bet. What do the notes suggest?',['Defend less against BB’s stronger 3-bet distribution','Defend more because BB’s overall range is wide','Call with every suited hand','Always 4-bet'],'BB can flat medium hands, so its 3-betting range is stronger than SB’s wider 3-bet-or-fold range.'],['BB faces an early open and a BTN 3-bet. Which cold 4-bet tier applies?',['The tighter opener anchors the tier','The wider button anchors the tier','Cold-call the entire medium range','Bluff every blocker'],'The notes default mixed pairings to the tighter player’s tier, keeping premiums constant.'],['Against a call-heavy opener, which 3-bet construction do the notes prefer?',['Linear: strong hands that dominate calls','Only blocker bluffs','Polarized with no medium value','Never 3-bet'],'A linear range values strong equity against the caller and deprioritizes bluffs with little fold equity.'],['Does more raw preflop equity always mean you should raise?',['No: range narrowing and equity realization matter','Yes: raw equity determines every action','Yes: every premium must always 4-bet','No: always limp instead'],'Raising narrows the opponent’s range, and a later jam can deny equity realization.']];let qi=Math.floor(Math.random()*qs.length),t=qs[qi];q.cardId=learn.find(x=>x.title.startsWith(['UTG vs','CO vs','BB cold','Playing vs','Equity realization'][qi]))?.id??c.id;[q.question,q.options,q.reason]=t;
}else{q.question=`Which statement matches “${c.title}”?`;let other=learn.filter(x=>x.id!==c.id).sort(()=>Math.random()-.5).slice(0,3);q.options=[c.text.split('. ')[0],...other.map(x=>x.text.split('. ')[0])];q.reason=c.text.split('. ')[0]+'.';}
let correct=q.options[0];q.options=q.options.map((x,i)=>({x,n:Math.random()})).sort((a,b)=>a.n-b.n).map(a=>a.x);q.answer=q.options.indexOf(correct);return q}
function start(){if([0,1,2,6].includes(selectedMode)&&!(selectedMode===6?rangesFor().filter(d=>d.spot==='RFI'&&['CO','BTN','SB'].includes(d.hero)):eligibleDatasets()).length){toast('No '+settings.tableSize+'-handed data loaded for this spot.');return}session={index:0,total:selectedMode===6?2:selectedMode===4?due().length:settings.length==='endless'?Infinity:Number(settings.length),used:new Set(),answers:[],current:null,feedback:null,size:null,reviewId:null};if(selectedMode===6){let date=settings.tableSize===6?day():day()+':4';if(!daily[date]){let rng=seeded(date);daily[date]={spots:[preSpot(rangesFor().filter(d=>d.spot==='RFI'&&['CO','BTN','SB'].includes(d.hero)),rng),postSpot(0,rng)],answers:[]};write('daily',daily)}session.dailyDate=date;session.total=2;session.index=daily[date].answers.length;session.answers=[...daily[date].answers];if(session.index>=2){summary();return}}nextSpot()}
function nextSpot(){if(session.index>=session.total){summary();return}session.feedback=null;session.size=null;session.reviewId=null;let spot;
if(selectedMode===4){let m=due().find(m=>!session.used.has('review:'+m.id));if(!m){summary();return}spot=structuredClone(m.spot);session.reviewId=m.id;session.used.add('review:'+m.id)}else if(selectedMode===6)spot=structuredClone(daily[session.dailyDate].spots[session.index]);else if(selectedMode===3){spot=postSpot();if(!spot){session.used.clear();spot=postSpot()}}else if(selectedMode===7)spot=quizSpot();else if(selectedMode===9)spot=equitySpot();else if(selectedMode===10)spot=villainSpot();else spot=preSpot();if(!spot){summary(selectedMode===10?'No unrepeated spots remain in this filter. Widen your filters to respect the 20-deal repeat window.':'You practiced every unique hand in this selection.');return}spot.tableSize??=settings.tableSize;spot.stackBb??=100;spot.rake??=0;session.current=spot;session.used.add(spot.id);if(spot.kind!=='quiz'&&spot.kind!=='equity')session.size=sizing(spot)[0];session.equityDraft='';screen='session';renderSession()}
function sizing(s){if(s.betSizes)return s.betSizes;return s.kind==='post'?[33,66,100,150]:s.spot==='RFI'?(s.hero==='SB'?[3,3.5,4,5]:[2.5,2.2,3,5]):s.spot==='Facing an Open'?((s.hero==='BTN'||s.hero==='CO'||s.hero==='HJ')?[7.5,6.25,10,12.5]:[s.villain==='SB'?12:10,7.5,12.5,15]):[22,25,30,40]}
function table(s){let seats=(s.tableSize||settings.tableSize)===4?['CO','BTN','SB','BB']:['LJ','HJ','CO','BTN','SB','BB'],hero=seats.indexOf(s.hero),vill=seats.indexOf(s.villain);return `<div class="table-space"><div class="felt"><span class="pot"><span class="chips" aria-hidden="true"><i></i><i></i><i></i></span>Pot ${s.pot.toFixed(1)}bb${s.bet?` · Bet ${s.bet.toFixed(1)}bb`:''}</span>${s.board?`<div class="board">${s.board.map(card).join('')}</div>`:''}</div>${seats.map((p,i)=>`<div class="seat ${p===s.hero?'hero-seat':p!==s.villain?'folded':''}"><strong title="${seatLabel(p)}">${seatShort(p)}${p===s.hero?' <span class="you-marker">YOU</span>':''}</strong><br>${p===s.hero?s.spot==='SB vs BB iso-raise'?'Limped 1bb':s.spot==='Facing a 3-Bet'?'Raised '+s.openSize+'bb':'Your action':p===s.villain?s.spot==='Facing a Limp'?'Limped 1bb':s.spot==='SB vs BB iso-raise'?'Iso-raised 4bb':s.kind==='post'?(s.bet?'Bet '+s.bet.toFixed(1)+'bb':'Checked'):s.spot==='Facing a 3-Bet'?'3-bet '+s.threeSize+'bb':s.betSizes?'Opened '+s.openSize+'bb':'Raised '+(p==='SB'?3:2.5)+'bb':['Facing a 3-Bet','SB vs BB iso-raise','Facing a Limp'].includes(s.spot)||i<hero?'Folded':'Waiting'}${p===s.villain?'<span aria-hidden="true"><i class="card-back"></i><i class="card-back"></i></span>':''}</div>`).join('')}</div>`}
let lastDealtSpot=null;
function preflopActions(s){return s.spot==='Facing a Limp'?['Check','Raise']:s.spot==='RFI'&&s.hero==='SB'&&'Limp' in s.frequencies?['Fold','Limp','Raise']:['Fold','Call','Raise']}
function actionKey(a){return a==='Fold'?'F':['Call','Check','Limp'].includes(a)?'C':'R'}
function actionLabel(s,a){return s.spot==='SB vs BB iso-raise'?(a==='Raise'?'Limp-raise':a==='Call'?'Limp-call':a):a}
function actionHint(s,a){return a==='Limp'?' · to 1bb':a==='Call'&&s.spot==='SB vs BB iso-raise'?' · 3bb more':['Raise','Bet'].includes(a)?' · '+session.size+(s.kind==='post'?'% pot':'bb'):''}
function renderSession(){if(session.current.kind?.startsWith('villain_')){renderVillain();return}if(session.current.kind==='equity'){renderEquity();return}let s=session.current,fb=session.feedback;let deal=lastDealtSpot!==s;lastDealtSpot=s;document.body.classList.toggle('two-color',!settings.fourColor);let actions=s.kind==='post'?(s.bet?['Fold','Call','Raise']:['Fold','Check','Bet']):preflopActions(s);app.innerHTML=`<main class="session ${deal?'deal':''}"><div class="session-head"><button data-quit>${svgIcon("back")} Save & quit</button><span>${modeLabel()}</span>${tableSwitch()}<span>Hand ${session.index+1} / ${session.total===Infinity?'∞':session.total}</span></div><div class="progress-track"><i style="width:${session.total===Infinity?((session.index%10)+1)*10:session.index/session.total*100}%"></i></div>${s.kind==='quiz'?`<div class="quiz ${learn[s.cardId]?.group.startsWith('Personal')?'exploit':''}"><div class="eyebrow">Concept quiz · ${esc(s.source)}</div><h2>${esc(quizCopy(s,s.question))}</h2><div class="quiz-options">${s.options.map((o,i)=>`<button data-answer="${i}" ${fb?'disabled':''} class="${fb?.pick===i?'picked':''}">${i+1}. ${esc(quizCopy(s,o))}</button>`).join('')}</div></div>`:`<h2 class="session-title">${s.spot==='RFI'?'Your move, '+seatShort(s.hero):s.spot}</h2><div class="session-label">${s.kind==='pre'?`${seatShort(s.hero)}${s.villain?' vs '+seatShort(s.villain):''} · ${term(s.spot==='RFI'?'RFI':s.spot==='Facing a Limp'?'Isolation raise':s.spot==='SB vs BB iso-raise'?'Limp response':s.spot==='Facing an Open'?'3-bet':'4-bet')}`:'Heuristic pack · '+(s.hero==='BTN'?'In position':'Out of position')} · 100bb</div>${table(s)}<div class="hero-hand">${s.cards.map(card).join('')}</div><p class="line">${esc(s.line)}</p>${s.kind==='post'?`<div class="math-strip">${s.bet?`<span>${term('pot odds')} ${pct(s.bet/(s.pot+2*s.bet))}</span><span>${term('MDF')} ${pct(s.pot/(s.pot+s.bet))}</span>`:`<span>${term('alpha')} ${pct((s.pot*session.size/100)/(s.pot+s.pot*session.size/100))} at ${session.size}% pot</span>`}${s.equity!==undefined?`<span>Assumed equity ${pct(s.equity)}</span>`:''}</div>`:''}`}
<div class="feedback ${fb?'revealed':''}" aria-live="polite">${fb?feedbackHTML(s,fb):`<div class="waiting">${s.kind==='quiz'?'Choose the statement that fits.':s.kind==='post'?'Think through the range, then choose your action.':'Take your time. Good decisions are built here.'}</div>`}</div><div class="action-zone">${fb?`<div class="after"><button ${s.kind==='quiz'?`data-read-card="${s.cardId}"`:s.kind==='pre'?'data-range':'data-spot-notes'}>${s.kind==='quiz'?'Read the card':s.kind==='pre'?'See the range':'Why this answer'}</button><button class="primary" data-next>${session.index+1>=session.total?'See results':'Next hand'} ${svgIcon('next')}</button></div>`:s.kind==='quiz'?'':`<div class="sizes" aria-label="Raise or bet sizing">${sizing(s).map((n,i)=>`<button class="${session.size===n?'selected':''}" data-size="${n}"><small>${i+1}</small> ${n}${s.kind==='post'?'%':'bb'}</button>`).join('')}</div><div class="actions ${actions.length===2?'two-actions':''}">${actions.map((a,i)=>`<button class="${['Raise','Bet'].includes(a)?'aggressive':''}" data-answer="${a}" ${s.kind==='post'&&!s.bet&&a==='Fold'?'disabled':''}>${actionLabel(s,a)}<small>${actionKey(a)}${actionHint(s,a)}</small></button>`).join('')}</div>`}<div class="keyhint">${fb?'ENTER next hand':s.spot==='Facing a Limp'?'C check · R iso-raise · 1–4 choose size':s.kind==='pre'&&preflopActions(s).includes('Limp')?'F fold · C limp · R raise · 1–4 choose size':'F fold · C call/check · R raise/bet · 1–4 choose size'}</div></div></main>`}
function frequencyHTML(s,pick){let entries=Object.entries(s.frequencies||{}).filter(([a,f])=>f>.0001);return `<div class="freq" aria-label="${s.kind==='pre'?handReadout(s.hand,s.frequencies):'Action frequencies'}">${entries.map(([a,f])=>`<span class="${a===pick||a.includes('Bet')&&pick==='Raise'?'picked':''}" style="width:${f*100}%;background:${colors[a]||'var(--call)'}" title="${s.kind==='pre'?s.hand+', when you hold this hand: ':''}${a} ${pct(f)}">${f>=.07?`${a} ${pct(f)}`:''}</span>`).join('')}</div><div class="source">${s.kind==='pre'?handReadout(s.hand,s.frequencies):entries.map(([a,f])=>`${a} ${pct(f)}`).join(' · ')} · Your pick: ${pick}</div>`}
function feedbackHTML(s,f){return `<div class="verdict ${f.score===0?'bad':''}"><strong>${f.verdict}</strong><span class="grade">${f.grade}</span></div>${s.kind==='quiz'?`<p><strong>${esc(quizCopy(s,s.options[s.answer]))}</strong></p>`:frequencyHTML(s,f.pick)}<p>${esc(s.kind==='quiz'?quizCopy(s,f.reason):f.reason)}</p>${f.sizeNote?`<p>${esc(f.sizeNote)}</p>`:''}<div class="source">${s.kind==='post'?esc(s.engine||'Heuristic strategy · exact math'):esc(s.label)} · ${esc(s.source)} · ${s.tableSize||settings.tableSize}-handed</div>`}
function evaluate(s,pick,size){if(s.kind==='quiz'){let yes=Number(pick)===s.answer;return{pick:Number(pick),score:yes?1:0,verdict:yes?'Correct':'Mistake',grade:yes?'Perfect':'Blunder',reason:s.reason}}let actual=pick;if(s.kind==='pre'&&s.spot==='Facing a 4-Bet'&&pick==='Raise')actual='5-Bet';if(s.kind==='pre'&&pick==='Raise')actual=s.spot==='Facing an Open'?'3-Bet':s.spot==='Facing a 3-Bet'?'4-Bet':s.spot==='Facing a 4-Bet'?'5-Bet':'Raise';let frequency=s.frequencies[actual]||0,score=s.betSizes?Number(SpotEngine.baselineAccepts(SpotEngine.adapter(s),actual)):frequency>=.5?1:frequency>=.25?.5:0,sizeNote='';if(s.kind==='pre'&&pick==='Raise'){let valid=s.betSizes?s.betSizes.includes(size):s.spot==='RFI'?(s.hero==='SB'?size>=3&&size<=3.5:size>=2.2&&size<=3):s.spot==='Facing an Open'?size===(['BTN','CO','HJ'].includes(s.hero)?7.5:s.villain==='SB'?12:10):size>=22&&size<=25;if(!valid)sizeNote=`${score?'Right decision, off size:':'Sizing note:'} the baseline ${s.spot==='Facing a Limp'?'iso-raises to 4bb':s.spot==='SB vs BB iso-raise'?'limp-raises to '+s.betSizes[0]+'bb total':s.spot==='RFI'?'opens to '+(s.hero==='SB'?3:2.5)+'bb':s.spot==='Facing an Open'?'uses 3× in position or 4× out of position':'uses a 22–25bb 4-bet in this simplified tree'}.`}
if(s.kind==='post'&&['Raise','Bet'].includes(pick)&&s.sizeClass){let cls=size<=33?'small':size<=100?'large':'overbet';if(cls!==s.sizeClass)sizeNote=`Right decision, off size: this pack uses the ${s.sizeClass} class (${s.sizeClass==='small'?'33%':'66–100%'} pot).`}
let best=Object.entries(s.frequencies).sort((a,b)=>b[1]-a[1])[0][0];return{pick,score,verdict:score===1?'Correct':score===.5?'Acceptable mix':'Mistake',grade:score===1&&!sizeNote?'Perfect':score>0?'Fine':frequency>0?'Leak':'Blunder',sizeNote,reason:s.kind==='post'?s.reason:`${s.label.startsWith('Constructed')?'The constructed chart':'The chart'} ${best==='Fold'?'folds':best==='Limp'?'limps':best==='Check'?'checks':best==='Call'?'calls':'raises'} ${s.hand}${score===.5?'; your action is an acceptable mix':''}. ${s.reason}`}}
function record(s,f){if(s.kind?.startsWith('villain_')){recordVillain(s,f);return}if(s.kind==='equity'){recordEquity(s,f);return}let row={at:Date.now(),tableSize:s.tableSize||settings.tableSize,stackBb:100,rake:0,source:s.source,kind:s.kind,position:s.hero,spot:s.spot,mode:modes[selectedMode][0],score:f.score,hand:s.hand||s.id};progress.push(row);write('progress',progress);session.answers.push(row);if(selectedMode===6){daily[session.dailyDate].answers=session.answers;write('daily',daily)}let m=mistakes.find(m=>rowSize(m.spot)===(s.tableSize||settings.tableSize)&&m.id===(session.reviewId||s.id));if(f.score===0){if(!m){m={id:s.id,spot:structuredClone(s),wrongPick:f.pick,correctAnswer:s.kind==='quiz'?s.answer:s.frequencies,consecutive:0,stage:0,due:Date.now(),misses:0};mistakes.push(m)}m.consecutive=0;m.stage=session.reviewId?Math.min((m.stage||0)+1,3):0;m.misses++;m.due=Date.now()+[0,1,3,7][m.stage]*86400000;m.wrongPick=f.pick;}else if(m&&session.reviewId){m.consecutive++;m.stage=Math.min((m.stage||0)+1,3);if(m.consecutive>=2)mistakes=mistakes.filter(x=>x.id!==m.id);else m.due=Date.now()+[0,1,3,7][m.stage]*86400000}write('mistakes',mistakes)}
function answer(pick){if(!session||session.feedback)return;let s=session.current;session.feedback=evaluate(s,pick,session.size);record(s,session.feedback);feedbackBlip(session.feedback.score);renderSession()}
function advance(){session.index++;if(selectedMode!==10&&selectedMode!==4&&selectedMode!==6&&(selectedMode!==9||filters.choice==='Decide the Call')){let m=due().find(m=>!session.used.has('repeat:'+m.id)&&!m.spot.kind?.startsWith('villain_')&&!session.used.has(m.spot.id)&&m.spot.id!==session.current.id&&m.misses>0);if(m&&session.index<session.total&&session.index%5===0){session.feedback=null;session.size=null;session.current=structuredClone(m.spot);session.reviewId=m.id;session.used.add('repeat:'+m.id);session.size=sizing(session.current)[0];renderSession();return}}nextSpot()}
function summary(note=''){screen='results';let a=session?.answers||[];let closings=['A clean session. Nicely played.','Logged. The baseline moves a little every day.','That is the work. Same time tomorrow.'];if(a.some(x=>x.score===0||(x.kind==='equity'&&x.score<1)))closings.push('Mistakes are data. They are already in your review queue.');session.closing??=rand(closings);shell(`<div class="page"><div class="stage-banner">STAGE CLEAR</div><div class="result-mascot">${tiger}</div><div class="eyebrow">Practice complete</div><h1>Every hand adds up.</h1><p class="muted">${note||session.closing}</p><div class="metrics"><div class="metric"><strong>${a.length}</strong><span>Decisions</span></div><div class="metric"><strong>${accuracy(a)}</strong><span>Weighted accuracy</span></div><div class="metric"><strong>${due().length}</strong><span>Due for review</span></div></div><div class="panel"><h3>${a.length&&a.every(x=>x.score===1)?'A clean session. Nicely played.':'Keep the reasoning, not just the answer.'}</h3><p class="muted">${a.filter(x=>x.score===0||(x.kind==='equity'&&x.score<1)).length} mistakes saved. Correct review answers twice in a row retire a spot.</p><div class="choices"><button class="primary" data-go="home">Back to practice</button><button data-go="progress">View progress</button></div></div></div>`)}
function totals(d){let eligible=d.eligible||d.cells.map(c=>c.hand),den=eligible.reduce((n,h)=>n+combo(h),0),out={};for(let a of Object.keys(d.targets))out[a]=d.cells.filter(c=>eligible.includes(c.hand)).reduce((n,c)=>n+combo(c.hand)*(c.frequencies[a]||0),0)/den*100;return out}
// Presentation-only labels. Frequencies, targets and their denominators stay unchanged.
const seatLabel=p=>p==='LJ'?'LJ (UTG in 6-max)':p;
const seatShort=p=>p==='LJ'?'LJ / UTG':p;
const aliasNotes=text=>String(text).replace(/\bUTG\b/g,'UTG (LJ in 6-max)');
function rangeTitle(d){if(d.spot==='SB vs BB iso-raise')return d.spot;if(d.spot==='Facing a Limp')return 'BB vs SB limp';return d.hero==='LJ'&&d.spot==='RFI'?'LJ · RFI (UTG in 6-max)':`${seatLabel(d.hero)}${d.villain?' vs '+seatLabel(d.villain):''} · ${d.spot}`}
function handReadout(hand,frequencies){return `${hand}, when you hold this hand: `+Object.entries(frequencies).map(([a,f])=>a+' '+pct(f)).join(' · ')}
function rangeScope(d){if(d.denominator==='limp range')return 'of all hands dealt in this seat that are in the SB limp range';return d.denominator==='opener range'?'of all hands dealt in this seat that are in the opening range':'of all hands dealt in this seat'}
function rangeNotes(d,t){
 if(d.spot==='RFI'){
  const match=d.notes.match(/^Seed ([\d.]+)%; target ([\d.]+)%\. Adjustments: (.*)$/);
  if(match){const parts=match[3].split('. SB'),adjustments=parts[0],extra=parts.length>1?' SB'+parts.slice(1).join('. SB'):'';return `Range check: this grid opens ${t.Raise.toFixed(2)}% of hands; target ${d.targets.Raise.toFixed(1)}% (Pokalab). ${Math.abs(t.Raise-d.targets.Raise)<=1?'Pass, within tolerance.':'Outside tolerance.'} Adjustments applied to the seed data: ${adjustments}.${extra}`}
 }
 if(d.id==='open-BTN-CO')return 'A8s–A3s, when you hold this hand: 3-Bet 85% (heuristic selection within the published per-hand 77–99% band). Residual cells are constructed. Named hand frequencies retained.';
 if(d.denominator==='opener range')return 'Whole opening range: Fold 25% and 4-Bet 16% of all hands dealt in this seat that are in the opening range, chosen from the published bands. The distribution for each hand is heuristic. Tiger’s UTG (LJ in 6-max) study-note frequencies are taught separately, not substituted for this chart.';
 return d.notes;
}
function quizCopy(q,text){
 const c=learn[q.cardId],out=aliasNotes(text);
 if(c?.title.startsWith('UTG vs')&&/%/.test(out))return `Whole opening range: ${out} (of all hands dealt in this seat that are in the opening range).`;
 if(q.question.includes('share of the range is MDF')&&/%/.test(out)&&text!==q.question)return `Whole defending range (of all hands dealt that reach this spot): ${out}`;
 if(q.question.includes('fold frequency does a pure bluff need')&&/^\d+%$/.test(out))return `Whole opponent range: ${out} of all hands dealt to the opponent that reach this spot`;
 if(/MDF \d+%/.test(out))return out.replace(/MDF (\d+%)/g,'MDF $1 of all hands dealt that reach this spot (whole defending range)');
 return out;
}
function gridHTML(d,highlight){let acts=Object.keys(d.cells[0].frequencies);return `<div class="grid" role="group" aria-label="13 by 13 hand range">${d.cells.map(c=>{let sum=0,stops=Object.entries(c.frequencies).filter(([a,f])=>f>0).map(([a,f])=>{let start=sum;sum+=f*100;return `${a==='Fold'?'#303931':a==='Limp'?'var(--cyan)':a==='Check'?'var(--call)':a==='Call'?'#647969':'#a8c977'} ${start}% ${sum}%`});let style=stops.length===1?stops[0].split(' ')[0]:`linear-gradient(90deg,${stops.join(',')})`;return `<button class="cell ${d.denominator==='limp range'&&!d.eligible.includes(c.hand)?'outside-range':''} ${c.hand===highlight?'highlight':''}" style="background:${style};${c.action==='Fold'||c.action==='Call'?'':'color:#14200e'}" data-cell="${c.hand}" data-dataset="${d.id}" aria-label="${d.denominator==='limp range'&&!d.eligible.includes(c.hand)?c.hand+', when you hold this hand: outside the SB limp range; this node is not reached.':handReadout(c.hand,c.frequencies)}">${c.hand}</button>`}).join('')}</div><div class="legend">${acts.map(a=>`<span><i style="background:${colors[a]}"></i>${a}</span>`).join('')}</div><p class="source">Pairs on diagonal · Suited above · Offsuit below · Whole-range summaries are combination-weighted across 1,326 possible starting hands${d.denominator==='limp range'?' (response rates conditional on the SB limp range; dim cells cannot reach this node)':d.denominator==='opener range'?' (response rates conditional on opener range)':''}.</p>`}
function chartContent(d,highlight){let t=totals(d);return `<h3>${rangeTitle(d)}</h3>${gridHTML(d,highlight)}<div class="grid-info" id="cell-info">${highlight?handReadout(highlight,d.cells.find(c=>c.hand===highlight).frequencies):'Tap any hand to see what to do when you hold this hand.'}</div><p class="source">${esc(d.label)}<br>${esc(d.source)}</p><p class="source">${esc(rangeNotes(d,t))}</p><div class="checks">${Object.entries(d.targets).map(([a,n])=>`<span class="${Math.abs(t[a]-n)<=1?'check-good':'check-bad'}">${Math.abs(t[a]-n)<=1?'✓':'!'} Whole range: ${a} ${t[a].toFixed(2)}% ${rangeScope(d)} · target ${n.toFixed(1)}%</span>`).join('')}</div>`}
function charts(){let ds=rangesFor();if(!ds.length){shell(`<div class="page"><h1>A range, not a guess.</h1>${missingRangeMessage()}</div>`,'Charts');return}let d=ds.find(d=>d.id===chartId)||ds[0];chartId=d.id;let allGood=ds.every(d=>Object.entries(d.targets).every(([a,n])=>Math.abs(totals(d)[a]-n)<=1));shell(`<div class="page"><div class="eyebrow">The baseline library</div><h1>A range, not a guess.</h1><p class="muted">Every range in the baseline, hand by hand.</p><p class="muted">${settings.tableSize===4?'Cash · 100bb · No rake · No ante. Opens 2.5bb; SB raises to 3bb or completes to 1bb. BB isolates a limp to 4bb.':'Cash · 100bb · No rake · Opens 2.5bb (SB 3bb, raise-or-fold).'}</p><div class="chart-pickers"><select id="chart-spot" aria-label="Chart spot">${[...new Set(ds.map(x=>x.spot))].map(s=>`<option ${s===d.spot?'selected':''}>${s}</option>`).join('')}</select><select id="chart-pos" aria-label="Chart positions">${ds.filter(x=>x.spot===d.spot).map(x=>`<option value="${x.id}" ${x.id===d.id?'selected':''}>${seatLabel(x.hero)}${x.villain?' vs '+seatLabel(x.villain):''}</option>`).join('')}</select></div><section class="panel">${chartContent(d)}</section><details class="panel"><summary class="${allGood?'check-good':'check-bad'}">${allGood?'✓ All '+ds.length+' grids pass':'! Data check failed'} · Built-in combination check</summary><p class="source">Every grid is checked on this page load. Individual hand allocations can be heuristic even when the aggregate check passes.</p>${ds.map(x=>`<div class="stats-row"><span>${rangeTitle(x)}</span><span>${Object.entries(totals(x)).map(([a,n])=>`Whole range: ${a} ${n.toFixed(1)}% ${rangeScope(x)}`).join(' / ')}</span></div>`).join('')}</details>${equitySelfCheck()}</div>`,'Charts')}
function modal(body){let el=document.createElement('div');el.className='modal';el.innerHTML=`<section class="modal-content" role="dialog" aria-modal="true"><button class="close" data-close aria-label="Close dialog">${svgIcon("close")}</button>${body}</section>`;document.body.append(el);el.querySelector('[data-close]').focus();el.onclick=e=>{if(e.target===el||e.target.closest('[data-close]'))el.remove()}}
function showLearn(){let groups=[...new Set(learn.map(x=>x.group))];if(cardId!==null&&screen==='card'){showCard(cardId);return}shell(`<div class="page"><div class="eyebrow">Tiger’s study notes</div><h1>Understand the why.</h1><p class="muted">Your study notes, one idea at a time. Personal notes, not solver output.</p><div class="choices">${groups.map(g=>`<button class="${learnGroup===g?'selected':''}" data-group="${esc(g)}">${groupLabel(g)}</button>`).join('')}</div>${(learnGroup?[learnGroup]:groups).map(g=>`<section class="panel notebook ${g.startsWith('Personal')?'exploit':''}"><h3 class="notebook-divider">${groupLabel(g)} · ${learn.filter(c=>c.group===g).length}</h3>${g.startsWith('Personal')?'<p class="source">Personal exploit notes, not GTO</p>':''}<div class="study-list">${learn.filter(c=>c.group===g).map(c=>`<button data-card="${c.id}"><span><span class="study-index" aria-hidden="true">${String(c.id+1).padStart(2,'0')}</span>${esc(aliasNotes(c.title))}${c.title==='MES against Ben'?'<span class="tag home-game">Home game</span>':''}</span><span class="muted">${svgIcon("next")}</span></button>`).join('')}</div></section>`).join('')}</div>`,'Learn')}
function showCard(id){let c=learn.find(c=>c.id===Number(id));if(!c)return;cardId=c.id;screen='card';shell(`<div class="page"><button class="back" data-go="learn">${svgIcon("back")} All study notes</button><div class="eyebrow ${c.group.startsWith('Personal')?'exploit-label':''}">${groupLabel(c.group)}</div><h1 class="${c.title.length>55?'long-heading':''}">${esc(aliasNotes(c.title))}</h1><p class="source byline">Tiger’s study notes · Appendix A5</p><span class="tag ${c.group.startsWith('Personal')?'exploit-label':''}">${esc(c.label)}</span><div class="panel"><p class="reading">${esc(aliasNotes(c.text))}</p>${c.title.startsWith('Bunching')?'<p class="notice">Context note: this personal note mentions shallow-stack effects. The trainer itself only deals 100bb cash spots.</p>':''}</div><div class="choices"><button data-card="${Math.max(0,c.id-1)}" ${c.id===0?'disabled':''}>${svgIcon("back")} Previous</button><button class="primary" data-quiz-group="${esc(c.group)}">Quiz me on this</button>${c.title==='Rule of 2 and 4'?'<button class="primary" data-equity-lab>Drill this</button>':''}<button data-card="${Math.min(learn.length-1,c.id+1)}" ${c.id===learn.length-1?'disabled':''}>Next ${svgIcon("next")}</button></div></div>`,'Learn')}
function aggregate(key){let out={};for(let p of progress.filter(x=>rowSize(x)===settings.tableSize)){let k=p[key]||'Other';(out[k]??=[]).push(p)}return Object.entries(out).map(([name,a])=>({name,n:a.length,score:a.reduce((s,x)=>s+x.score,0)/a.length}))}
function statRows(a){return a.length?a.map(x=>`<div><div class="stats-row"><span>${esc(seatLabel(x.name))}</span><span>${pct(x.score)} weighted accuracy · ${x.n} hands</span></div><div class="statbar"><i style="width:${x.score*100}%"></i></div></div>`).join(''):'<p class="muted">Your first session will start the picture.</p>'}
function showProgress(){let scoped=progress.filter(x=>rowSize(x)===settings.tableSize),leaks=aggregate('spot').concat(aggregate('position')).filter(x=>x.n>=20).sort((a,b)=>a.score-b.score).slice(0,5);shell(`<div class="page"><div class="eyebrow">Your practice, over time</div><h1>Find your next edge.</h1>${xpDisplay()}${villainProgressHTML()}<div class="metrics"><div class="metric"><strong>${scoped.length}</strong><span>${settings.tableSize}-handed decisions</span></div><div class="metric"><strong>${accuracy(scoped)}</strong><span>Weighted accuracy</span></div><div class="metric"><strong>${mistakes.filter(m=>rowSize(m.spot)===settings.tableSize).length}</strong><span>In review</span></div></div><section class="panel"><h3>By position</h3>${statRows(aggregate('position'))}</section><section class="panel"><h3>By spot type</h3>${statRows(aggregate('spot'))}</section><section class="panel"><h3>Your biggest leaks</h3>${leaks.length?statRows(leaks):'<p class="muted">Train at least 20 decisions in a category to see a meaningful pattern.</p>'}</section><section class="panel"><h3>Keep your practice with you</h3><p class="muted">Progress is stored on this browser. Export a backup before switching devices.</p><div class="choices"><button data-export>Export JSON</button><button data-import>Import JSON</button><input id="import-file" type="file" accept="application/json" hidden></div><p class="source" id="import-status"></p></section></div>`,'Progress')}
function showSettings(){shell(`<div class="page"><div class="eyebrow">Make yourself comfortable</div><h1>Your table.</h1><section class="panel"><div class="setting"><div>Table size<p class="source">Four-handed includes constructed baseline ranges, not solver output. Optional solver imports override matching spots. Existing six-handed charts remain available.</p></div><select data-setting="tableSize"><option value="4" ${settings.tableSize===4?'selected':''}>4-handed</option><option value="6" ${settings.tableSize===6?'selected':''}>6-handed</option></select></div><div class="setting"><span>Four-color deck</span><input type="checkbox" data-setting="fourColor" ${settings.fourColor?'checked':''}></div><div class="setting"><span>Session length</span><select data-setting="length">${[10,20,'endless'].map(n=>`<option value="${n}" ${String(settings.length)===String(n)?'selected':''}>${n==='endless'?'Endless':n+' hands'}</option>`).join('')}</select></div><div class="setting"><span>Feedback sound</span><input type="checkbox" data-setting="sound" ${settings.sound?'checked':''}></div></section><section class="panel"><h3>Import ranges</h3><p class="muted">${settings.tableSize===4&&!rangesFor().length?'No 4-handed no-rake solver ranges loaded. ':''}Optionally load solver-export JSON. In four-handed mode, imports replace matching constructed baseline ranges for charts and grading. Other defaults remain available. Imports stay in this browser; keep your range file as a backup.</p><p class="source">JSON: {ranges: [...]}. Each range supplies tableSize (4 or 6), stackBb (100), rake (0), hero, villain, spot (RFI, Facing an Open, Facing a 3-Bet, Facing a 4-Bet, Facing a Limp, SB vs BB iso-raise), source, betSizes (bb), and 169 cells with hand and frequencies (0–1, summing to 1). Use action names Raise, Call, Fold, 3-Bet, 4-Bet, 5-Bet, Limp, Check. Raise and Call mean limp-raise and limp-call in SB vs BB iso-raise. Non-RFI ranges also require pot, line, openSize and threeSize when facing a re-raise, in bb. Optional eligible lists the opening-range hand classes. Optional targets use percentages.</p><input type="file" id="range-file" accept="application/json" aria-label="Import solver ranges">${rangeReport()}${importedRanges.length?`<h3>Imported solver grids</h3>${importedRanges.map(d=>`<div class="setting"><div>${esc(rangeTitle(d))} · ${d.tableSize}-handed<p class="source">${esc(d.source)}</p></div><button data-remove-range="${esc(d.id)}">Remove import</button></div>`).join('')}`:''}<h3>Import exact-spot baselines</h3><p class="source">JSON {baselines: [...]}; each entry needs spotId, tableSize, source, and normalized frequencies keyed by the seed’s option IDs. This attaches solver answers only to the exact named spot.</p><input type="file" id="spot-baseline-file" accept="application/json" aria-label="Import exact-spot baselines"></section><p class="source">Always cash games · 100bb · No rake. No accounts, tracking, analytics, or external fonts.</p><p class="source" id="offline-status">Checking offline cache…</p></div>`);if('serviceWorker'in navigator)navigator.serviceWorker.ready.then(()=>{caches.has('tiger-gto-v21').then(ok=>{let el=$('#offline-status');if(el)el.textContent=ok?'Offline files cached. Practice is available without a connection.':'Offline cache is still preparing.'})})}
function showGlossary(){shell(`<div class="page"><div class="eyebrow">Plain language, always</div><h1>Poker, translated.</h1>${Object.entries(glossary).map(([t,d])=>`<section class="panel"><h3>${t}</h3><p class="muted">${d}</p></section>`).join('')}</div>`)}
function methodology(){shell(`<article class="page"><div class="eyebrow">Know what you’re practicing</div><h1>Methodology.</h1><section class="panel"><h3>What this app covers</h3><p>This app trains cash game poker only: 6-handed and 4-handed No-Limit Hold'em, 100bb stacks, no rake. It has no tournament content: no ICM, no antes, no short-stack push/fold charts, because the games it prepares you for are full-stack cash games.</p></section><section class="panel"><h3>The preflop baseline</h3><p>Open to 2.5bb, or 3bb from the small blind. In position, 3-bet to about 3× the open; out of position, about 4×. The six-handed small-blind baseline remains raise-or-fold. Four-handed SB uses Raise / Limp / Fold: raise to 3bb or complete to 1bb. SB acts out of position postflop against BB; BB checks for free or iso-raises to 4bb total. After a BB iso-raise, the constructed SB response calls 3bb more or limp-raises to 12bb total with listed hands.</p><p>Ranges must match the table size, stack depth and no-rake assumptions. The four-handed hand lists are constructed baselines, not solver output.</p><p>RFI hand-list seeds are simplified to pure actions and adjusted at borderline suited hands to meet the supplied targets. Every JSON grid records its adjustment and source. Stored frequencies drive frequency-weighted scoring: 50%+ earns a full point, 25–49% half a point, and under 25% is a mistake.</p><p>Constructed grids match supplied aggregate frequencies, but their individual hand allocations are <strong>heuristic</strong>, not solver outputs. For matchups with no exact seat rate, a target is selected within the supplied band; call rates outside BTN vs CO are heuristic assumptions. Facing-a-3-bet targets are conditional on the opener’s range. The published BTN vs CO named frequencies are retained; A8s–A3s use 85% within the supplied 77–99% band.</p><p>Seed lists and rounded percentage targets need not coincide exactly. The Charts self-check uses combination weights: pairs 6, suited 4, offsuit 12, with a one-percentage-point tolerance.</p></section><section class="panel"><h3>Postflop: math and judgment</h3><p>Exact math: pot odds = bet / (pot + bet + call); MDF = pot / (pot + bet); alpha = 1 − MDF. Percentages are rounded for display; calculations use unrounded values. A displayed 33% or 67% reference bet can represent the familiar one-third or two-thirds approximation.</p><p>The Facing a Bet pack supplies assumed equity explicitly and judges the call using pot odds. These equity inputs are illustrative, not calculated against a solved range. MDF describes a whole range, not whether a particular hand must call. The pack’s heuristic is to meet MDF with an uncapped flop/turn range and defend less out of position against large bets.</p><p>C-Bet or Check and River Decisions are curated heuristics. Dry high boards support small bets; wet boards support more checking and larger polarized bets; low boards can favor the caller. River blockers only mean something relative to the stated value and bluff assumptions. There is no universal blocker-based call verdict without an opponent range.</p><p>Postflop sizing classes: small 33%; large 66–100%; overbet 150%. Opening size is graded separately from the action. No solver frequency is claimed for a heuristic pack. Four-handed preflop uses ten bundled constructed baseline ranges, not solver output: CO/BTN/SB opens, SB vs CO/BTN opens, BB vs CO/BTN/SB opens, BB vs SB limp, and SB vs BB iso-raise. Imported solver grids override matching defaults; removing an import restores the defaults. No six-handed grid is reused. Historical rows without a table-size tag are treated as the original six-handed baseline.</p></section><section class="panel"><h3>Tiger’s study notes</h3><p>Learn and Concept Quiz content comes from the user’s own study notes and is not solver output. All Appendix A5 cards are preserved, including personal exploit notes. Where notes differ from the baseline charts, the notes are taught as written, not silently merged into chart data.</p><p>For example, the study-note UTG response frequencies differ from the aggregate preflop construction. Personal shorthand and context-dependent principles are retained as notes, not certified as optimal play.</p></section><section class="panel"><h3>Equity Lab: outs and enumeration</h3><p>Equity Lab drills the estimate you make at the table. Clean outs are the cards that complete the named draw and put you ahead of the stipulated villain hand on the next card. Cards that give villain a stronger hand or only tie are excluded; on the flop, villain can still redraw on the river. The rule of 2 and 4 turns that count into a quick percentage. Alongside it, the app shows the exact figure, computed by enumerating every remaining runout against the stipulated hand. That is arithmetic, not a solver: no ranges are solved and no strategy is computed.</p></section><section class="panel"><h3>Sources supplied in the build spec</h3>${sources.map(s=>`<p class="source">${esc(s).replace(/https:\/\/[^\s]+/g,url=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${url}</a>`)}</p>`).join('')}<p class="source">No solver sites were scraped. The provided appendix is the encoded source material; source links have not been independently audited.</p></section><p class="notice">This app trains baseline poker decisions. Constructed baseline ranges are not solver output. It is a study tool, not a solver.</p></article>`)}
function exportProgress(){let blob=new Blob([JSON.stringify({version:1,progress,mistakes,villainProgress},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tiger-gto-progress-'+day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importProgress(file){try{let obj=JSON.parse(await file.text());if(obj.version!==1||!Array.isArray(obj.progress)||!Array.isArray(obj.mistakes)||!obj.progress.every(p=>Number.isFinite(p.at)&&(p.kind==='equity'?[0,.25,.5,.75,1]:[0,.5,1]).includes(p.score)&&['pre','post','quiz','equity','villain'].includes(p.kind))||!obj.mistakes.every(m=>typeof m.id==='string'&&m.spot&&['pre','post','quiz','equity','villain_real','villain_fabricated'].includes(m.spot.kind)&&Number.isFinite(m.due)))throw Error('Invalid backup');if(obj.villainProgress!==undefined&&(!Array.isArray(obj.villainProgress)||obj.villainProgress.some(p=>!Number.isFinite(p.at)||!['correct','lean','baseline_unavailable','baseline_miss','exploit_miss','intentional_deviation'].includes(p.classification))))throw Error('Invalid villain backup');progress=obj.progress;mistakes=obj.mistakes;if(obj.villainProgress){villainProgress=obj.villainProgress;writeVillain('progress',villainProgress)};write('progress',progress);write('mistakes',mistakes);showProgress();toast('Progress and mistake queue restored.')}catch{toast('That file is not a valid GTO Trainer backup. Your data was kept.')}}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.removeRange){removeRangeImport(b.dataset.removeRange);return}if(b.dataset.tableSize){changeTableSize(Number(b.dataset.tableSize));return}if(b.dataset.go){go(b.dataset.go);return}if(b.hasAttribute('data-mode')){selectedMode=Number(b.dataset.mode);filters={};if(selectedMode===5)go('charts');else if(selectedMode===8)go('learn');else go('setup')}if(b.dataset.choice){filters.choice=b.dataset.choice;filters.matchup='';setup()}if(b.hasAttribute('data-equity-lab')){selectedMode=9;filters={choice:'All Drills'};go('setup')}if(b.hasAttribute('data-start'))start();if(b.dataset.answer!==undefined)answer(b.dataset.answer);if(b.dataset.size){session.size=Number(b.dataset.size);renderSession()}if(b.hasAttribute('data-next'))advance();if(b.hasAttribute('data-quit')){session=null;go('home')}if(b.hasAttribute('data-range')){let s=session.current,d=allRangeData().find(d=>d.id===s.dataset);modal(chartContent(d,s.hand))}if(b.hasAttribute('data-spot-notes')){let s=session.current;modal(`<h2>Why this answer</h2><p>${esc(s.reason)}</p><p class="source">${esc(s.label)}</p><p>${s.equityNote||'This example depends on the stated opponent range; it is not a universal solver verdict.'}</p>`)}if(b.dataset.cell){let d=allRangeData().find(x=>x.id===b.dataset.dataset),c=d.cells.find(x=>x.hand===b.dataset.cell),el=b.closest('.modal-content,.panel').querySelector('#cell-info');if(el)el.textContent=d.denominator==='limp range'&&!d.eligible.includes(c.hand)?c.hand+', when you hold this hand: outside the SB limp range; this node is not reached.':handReadout(c.hand,c.frequencies);b.closest('.grid').querySelectorAll('.highlight').forEach(x=>x.classList.remove('highlight'));b.classList.add('highlight')}if(b.dataset.term)modal(`<h3>${esc(b.dataset.term)}</h3><p>${esc(glossary[b.dataset.term]||'A poker study concept.')}</p>`);if(b.dataset.group){learnGroup=learnGroup===b.dataset.group?null:b.dataset.group;showLearn()}if(b.dataset.card!==undefined)showCard(b.dataset.card);if(b.dataset.readCard!==undefined)modal(`<h2>${esc(learn[b.dataset.readCard].title)}</h2><p class="reading">${esc(learn[b.dataset.readCard].text)}</p><p class="source">Tiger’s study notes · Personal notes, not solver output</p>`);if(b.dataset.quizGroup){selectedMode=7;filters={choice:b.dataset.quizGroup};go('setup')}if(b.hasAttribute('data-export'))exportProgress();if(b.hasAttribute('data-import'))$('#import-file').click()});
document.addEventListener('change',e=>{let t=e.target;if(t.id==='range-file'&&t.files[0]){importRanges(t.files[0]);return}if(t.id==='position-matchup'){filters.matchup=t.value;setup();return}if(t.id==='chart-spot'){chartId=rangesFor().find(d=>d.spot===t.value).id;charts()}if(t.id==='chart-pos'){chartId=t.value;charts()}if(t.id==='import-file'&&t.files[0])importProgress(t.files[0]);if(t.dataset.setting){let k=t.dataset.setting;if(k==='tableSize'){changeTableSize(Number(t.value));t.value=String(settings.tableSize);return}settings[k]=t.type==='checkbox'?t.checked:k==='tableSize'?Number(t.value):t.value==='endless'?'endless':Number(t.value);write('settings',settings);document.body.classList.toggle('two-color',!settings.fourColor)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.modal')?.remove();return}if(screen!=='session'||document.querySelector('.modal')||!session)return;if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;let k=e.key.toLowerCase();if(session.feedback){if(k==='enter'){e.preventDefault();advance()}return}if(session.current.kind?.startsWith('villain_')){let i=Number(k)-1;if(Number.isInteger(i)&&session.current.options[i])answerVillain(session.current.options[i]);return}if(session.current.kind==='equity'){if(k==='c'||k==='f'){e.preventDefault();submitEquity(k==='c'?'Call':'Fold')}return}if(session.current.kind==='quiz'){if(['1','2','3','4'].includes(k))answer(Number(k)-1);return}if(['1','2','3','4'].includes(k)){session.size=sizing(session.current)[Number(k)-1];renderSession()}if(['f','c','r'].includes(k)){let s=session.current;if(k==='f'&&s.kind==='post'&&!s.bet)return;let pick=k==='f'?'Fold':k==='c'?(s.kind==='pre'?preflopActions(s).find(a=>['Call','Check','Limp'].includes(a)):!s.bet?'Check':'Call'):s.kind==='post'&&!s.bet?'Bet':'Raise';if(s.kind==='pre'&&!preflopActions(s).includes(pick))return;answer(pick)}});
/* Landing-only demo: shared villain picker/grader; never calls a recorder. */
let heroDemoSpot=null,heroDemoFeedback=null;
const landingDescriptions={0:'Preflop decisions across the available seats.',1:'Opening and defense decisions from one seat.',2:'Opens, defenses, and responses to 3-bets.',3:'Postflop actions, bet sizing, and pot odds.',9:'Clean outs, equity estimates, and draw prices.',10:'Opponent-specific exploits from tracked hands and rules.',4:'Retries of decisions saved in your mistake queue.',5:'Hand-by-hand opening and response ranges.',6:'Two daily practice spots.',7:'Poker definitions and calculations from your notes.',8:'Study notes grouped by concept.'};
function pickHeroDemo(){
 if(heroDemoSpot)return heroDemoSpot;
 const pool=villainData.spots.filter(s=>SpotEngine.sample(s)!=='hidden');
 const real=pool.filter(s=>s.kind==='villain_real');
 let s=villainPicker.next(real);
 // The real-only subset has 20 entries. If all are recent, advance the same
 // picker once through its full pool to respect its existing 20-deal window.
 if(!s){villainPicker.next(pool);s=villainPicker.next(real)}
 if(!s)throw Error('No real villain demo is available.');
 s.gradingMode='exploit';heroDemoSpot=s;writeVillain('recent',villainPicker.snapshot());return s;
}
function heroDemoHTML(){const s=pickHeroDemo(),f=heroDemoFeedback;return `<section class="hero-demo" aria-labelledby="demo-heading"><div class="demo-heading"><span class="section-label">PLAY A REAL HAND</span><span class="demo-kind">${s.tableSize}-handed · ${esc(s.street)} · demo</span></div><h2 id="demo-heading">Tiger ${esc(s.heroPos)} vs ${esc(s.villain)} ${esc(s.villainPos)}</h2><div class="demo-table"><div class="felt"><div class="pot">Pot <span class="number">${s.potBb}bb</span> · To call <span class="number">${s.toCallBb}bb</span></div>${s.board.length?`<div class="board">${s.board.map(card).join('')}</div>`:'<span class="demo-street">Preflop</span>'}</div><div class="hero-hand">${s.heroHand.map(card).join('')}</div></div><details class="demo-history"><summary>Action to this decision</summary><ol>${s.history.map(h=>`<li>${esc(h)}</li>`).join('')}</ol><p class="source">${esc(s.tableSizeNote||'')} ${s.effectiveStackBb}bb effective in the logged hand.</p></details><div class="demo-evidence">${s.driverStats.map(d=>`<p><strong>${esc(s.villain)} · ${esc(d.label)}</strong> <span class="number">${d.value_pct!==undefined?d.value_pct+'%':d.value+'bb'}</span> <span class="number">(n=${d.n})</span></p>`).join('')}</div><div class="demo-answer" aria-live="polite">${f?`<div class="feedback revealed">${villainFeedback(s,f)}</div><button class="demo-continue" data-demo-continue>Keep drilling</button>`:`<div class="demo-options">${s.options.map(a=>`<button data-demo-answer="${esc(a)}">${esc(optionLabel(a))}</button>`).join('')}</div><span class="demo-note">Demo answers do not save progress.</span>`}</div></section>`}
function landingHome(){shell(`<section class="landing-hero"><div class="landing-intro"><div class="eyebrow">4 &amp; 6-HANDED CASH · 100BB · NO RAKE</div><h1>Poker drills built from real hands.</h1><p class="landing-description">Pot Geometry is a GTO study tool with drilling and equity exercises for 4- and 6-handed cash games. The villain spots are generated from real hands saved from online games against specific opponents, so you drill exploits against their actual tendencies, with every stat shown next to its sample size.</p><div class="landing-stats">11 modes · 47 drill setups · Villain profiles from tracked hands · Free, no account</div><button class="primary landing-start" data-landing-start>Start drilling ${svgIcon('next')}</button></div>${heroDemoHTML()}</section><section class="landing-modes" id="practice-modes" tabindex="-1"><div class="section-title"><h2>Practice modes</h2></div><div class="modes">${[0,1,2,3,9,10,4,5,6,7,8].map((i,order)=>`<button class="mode" data-mode="${i}"><span class="num">${String(order+1).padStart(2,'0')}</span><h3>${modes[i][0]}</h3><p>${landingDescriptions[i]}</p></button>`).join('')}</div></section>`)}
function answerHeroDemo(a){if(screen!=='home'||heroDemoFeedback||!heroDemoSpot)return;heroDemoFeedback={...SpotEngine.grade(heroDemoSpot,a,'exploit'),pick:a};document.querySelector('.demo-answer').innerHTML=`<div class="feedback revealed">${villainFeedback(heroDemoSpot,heroDemoFeedback)}</div><button class="demo-continue" data-demo-continue>Keep drilling</button>`}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.demoAnswer)answerHeroDemo(b.dataset.demoAnswer);if(b.hasAttribute('data-landing-start')||b.hasAttribute('data-demo-continue')){const el=document.getElementById('practice-modes');el?.scrollIntoView({block:'start',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});el?.focus({preventScroll:true})}});

async function init(){try{let index=await(await fetch('data/index.json')).json();[datasets,learn,sources]=await Promise.all([Promise.all(index.map(d=>fetch('data/'+d.id+'.json').then(r=>r.json()))),fetch('data/learn.json').then(r=>r.json()),fetch('data/sources.json').then(r=>r.json())]);fourHandedBaselines=await fetch('data/four-handed-baselines.json').then(r=>r.json());[opponentProfiles,villainData]=await Promise.all(['opponent_profiles.json','villain_spots_seed.json'].map(f=>fetch('data/'+f).then(r=>r.json())));SpotEngine.load(villainData,opponentProfiles);for(let d of allRangeData())for(let c of d.cells)c.classification=classify(d,c);go('home');if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').then(reg=>{if(reg.waiting)reg.waiting.postMessage('SKIP_WAITING')}).catch(()=>{});window.GTO={datasets,learn,packs,totals,evaluate,classify,preSpot,getState:()=>({progress,mistakes,settings,daily}),start,quizSpot,equity:EquityMath};}catch(e){app.innerHTML='<p class="loading">The practice files could not load. Please reconnect and reload once to prepare offline mode.</p>';console.error(e)}}init();
